@Composable
fun Counter() {
    var count by remember { mutableStateOf(0) }
    Button(onClick = { count++ }) {
        Text("count = $count")
    }
}

@Composable
fun Counter(value: Int, onIncrement: () -> Unit) {
    Button(onClick = onIncrement) {
        Text("count = $value")
    }
}

@Composable
fun NameField() {
    var name by rememberSaveable { mutableStateOf("") }
    TextField(value = name, onValueChange = { name = it })
}

@Composable
fun NameList(names: List<String>) {
    LazyColumn {
        items(names, key = { it }) { name ->
            Text(name)
        }
    }
}

@Composable
fun UserScreen(userId: String) {
    var name by remember { mutableStateOf("loading") }
    LaunchedEffect(userId) {
        name = loadName(userId)
    }
    Text(name)
}

class MainActivity : ComponentActivity() {
    override fun onStart() {
        super.onStart()
        registerListener()
    }

    override fun onStop() {
        unregisterListener()
        super.onStop()
    }
}

class CounterViewModel : ViewModel() {
    var count by mutableStateOf(0)
        private set

    fun increment() {
        count += 1
    }
}

fun openDetail(context: Context, id: String) {
    val intent = Intent(context, DetailActivity::class.java)
    intent.putExtra("itemId", id)
    context.startActivity(intent)
}

fun openWebsite(context: Context, url: String) {
    val intent = Intent(Intent.ACTION_VIEW, Uri.parse(url))
    if (intent.resolveActivity(context.packageManager) != null) {
        context.startActivity(intent)
    }
}

@Composable
fun PickImage() {
    val launcher = rememberLauncherForActivityResult(
        contract = ActivityResultContracts.GetContent()
    ) { uri: Uri? ->
        if (uri != null) onImagePicked(uri)
    }
    Button(onClick = { launcher.launch("image/*") }) {
        Text("pick")
    }
}

@Composable
fun ThemedText(text: String) {
    MaterialTheme {
        Text(text, color = MaterialTheme.colorScheme.onSurface)
    }
}

@Composable
fun AppTheme(dark: Boolean = isSystemInDarkTheme()) {
    MaterialTheme(colorScheme = if (dark) darkColorScheme() else lightColorScheme()) {
        Text("content")
    }
}

@Composable
fun CameraButton(
    onGranted: () -> Unit,
    onDenied: () -> Unit
) {
    val launcher = rememberLauncherForActivityResult(
        ActivityResultContracts.RequestPermission()
    ) { granted -> if (granted) onGranted() else onDenied() }
    Button(onClick = { launcher.launch(Manifest.permission.CAMERA) }) {
        Text("camera")
    }
}
